import{_ as t,o,c as r,a0 as a}from"./chunks/framework.C3yZ6M33.js";const u=JSON.parse('{"title":"Stores (persistence)","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/stores.md","filePath":"explanation/stores.md"}'),s={name:"explanation/stores.md"};function i(n,e,d,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="stores-persistence" tabindex="-1">Stores (persistence) <a class="header-anchor" href="#stores-persistence" aria-label="Permalink to &quot;Stores (persistence)&quot;">​</a></h1><p>The event log flows through an <code>EventStore</code> port; run state through <code>StateStore</code>; dead letters through <code>DeadLetterQueue</code>. All three live in <code>peregrin-store</code> — the bus appends, the runner reads, and neither knows which impl is behind the trait.</p><h2 id="built-in-implementations" tabindex="-1">Built-in implementations <a class="header-anchor" href="#built-in-implementations" aria-label="Permalink to &quot;Built-in implementations&quot;">​</a></h2><ul><li><code>MemoryStore</code> — in-memory <code>EventStore</code> + <code>StateStore</code>; the ephemeral default. Every <code>Runner::new</code> starts here: <code>peregrin campaign run</code> prints the returned log instead of persisting it (the v1 <code>handl run</code> semantics).</li><li><code>JsonStore</code> (<code>peregrin-store-json</code>) — append-only JSONL <code>EventStore</code>; durable across process exit. <code>peregrin campaign run --history &lt;path&gt;</code> swaps the log onto it, and <code>peregrin runs</code>, <code>explain</code>, and <code>log</code> read that same file back — the observability verbs are just readers of the store format. Reopened on the same path, the store resumes publish/first-seen order — that is what makes <code>--replay</code> runs possible.</li><li><code>MemoryDlq</code> / <code>NoopDlq</code> — dead-letter impls; the node plane keeps dead letters for the run&#39;s life (<code>MemoryDlq</code>), the bare default drops them.</li></ul><p>Not yet ported: the <code>JsonStateStore</code> half of the v1 json adapter — run state stays in-memory (ADR-0013).</p><h2 id="why-ports" tabindex="-1">Why ports? <a class="header-anchor" href="#why-ports" aria-label="Permalink to &quot;Why ports?&quot;">​</a></h2><p>The event log IS the workflow state. Different deployments need different storage: a file for single-process runs, a database for distributed workflows, in-memory for tests. The port lets you swap without touching the engine — composition happens once, in <code>peregrin_node::campaign</code> (<code>runner_with_log</code> is the JSONL-backed variant).</p><p><code>seen_types</code> — the store&#39;s O(1)-ish &quot;which types have been published&quot; view — is what <code>mode: all</code> eligibility checks against instead of scanning the full log per publish.</p><h2 id="crash-recovery-by-default" tabindex="-1">Crash recovery by default? <a class="header-anchor" href="#crash-recovery-by-default" aria-label="Permalink to &quot;Crash recovery by default?&quot;">​</a></h2><p>Not quite — the split is explicit in v2: the <em>default</em> is ephemeral (<code>MemoryStore</code>, the TS <code>handl run</code> behavior), and durability is the <code>--history</code> flag. The <code>create</code>d campaign units run with <code>--history</code> pointed at <code>$PEREGRIN_HOME/history.jsonl</code>, so deployed gates persist every event as it happens. Use <code>peregrin campaign run --replay &lt;log&gt;</code> to seed a run from a prior log.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./adapter-ports.html">Adapter ports</a> — the trait surfaces</li><li><a href="./../reference/queue-supersede.html">Queue &amp; supersede</a> — how queued triggers relate to the log</li><li><a href="./../reference/event-envelope.html">Event envelope</a> — what a log line contains</li></ul>',12)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
